target.command:
cd /home/john/mynotes/deterministic_equidistribution_theory/c_suite/out_large
awk -F, '
  # F residue-only gaps: Q,k -> gap_s0(col5), gap_s1(col6)
  FNR==NR { if(!/^#/ && $1!="Q") { g0[$1","$2]=$5; g1[$1","$2]=$6 } ; next }
  !/^#/ && $1!="window_id" && NF>=14 && $14==1 {
    Q=$7; k=$8; s=$9; W=$6; L=$4;
    # tilt distribution of shadows
    sc[s]++; if(L>=64) lsc[s]++;
    # Q distribution
    qc[Q]++;
    # join gap at this tilt
    key=Q","k; gap=-1;
    if(s=="1.0000") gap=g1[key]; else if(s=="0.0000") gap=g0[key];
    if(gap>=0){ n++; sx+=W; sy+=gap; sxy+=W*gap; sx2+=W*W; sy2+=gap*gap;
                if(L>=64){ ln++; lsy+=gap } }
  }
  END{
    print "=== shadow argmax TILT distribution ===";
    for(x in sc) printf "  s=%-7s  shadows=%-8d  long(>=64)=%d\n",x,sc[x],lsc[x]+0;
    print "=== shadow argmax MODULUS distribution ===";
    for(x in qc) printf "  Q=%-4s  shadows=%d\n",x,qc[x];
    print "=== |W| vs operator gap_ratio (argmax sector, s in {0,1}) ===";
    if(n){ corr=(n*sxy-sx*sy)/sqrt((n*sx2-sx*sx)*(n*sy2-sy*sy));
      printf "  n=%d  mean|W|=%.4f  mean gap_ratio=%.4f  corr(|W|,gap)=%.3f\n",n,sx/n,sy/n,corr;
      printf "  long windows(>=64): n=%d  mean gap_ratio=%.4f\n",ln,ln?lsy/ln:0 }
  }' fourier_comparison.csv shadow_search.csv | sort
